statement:
A football league keeps two tables:

- `Teams(team_id, team_name)`: one row per team; `team_id` is unique and so is `team_name`.
- `Matches(home_team_id, away_team_id, home_team_goals, away_team_goals)`: one row per match that was played; `(home_team_id, away_team_id)` is unique. Both ids are teams in `Teams` and are different, and the goal counts are non-negative.

A win is worth **3** points, a draw **1** point for each side and a loss **0**. Build the league table with one row per team that played at least one match (home or away) and the columns:

- `team_name`;
- `matches_played`: how many matches the team played, home and away together;
- `points`: its total points;
- `goal_for`: goals the team scored over all its matches;
- `goal_against`: goals its opponents scored against it;
- `goal_diff`: `goal_for - goal_against`.

Teams with no match are not listed. Order the rows by `points` descending, then `goal_diff` descending, then `team_name` ascending.

validator:
function validate(input) {
  const [{ Teams = [], Matches = [] }] = input;
  const teams = new Set(), names = new Set(), pairs = new Set();
  for (const [id, name] of Teams) {
    if (id === null) return 'Every team needs a team_id.';
    if (teams.has(id)) return `team_id ${id} appears twice in Teams.`;
    teams.add(id);
    if (name === null) return `Team ${id} needs a name.`;
    const key = String(name).toLowerCase();
    if (names.has(key)) return `Team name ${name} is used twice.`;
    names.add(key);
  }
  for (const [home, away, homeGoals, awayGoals] of Matches) {
    if (!teams.has(home) || !teams.has(away)) return `Match ${home} vs ${away} names a team that is not in Teams.`;
    if (home === away) return `Team ${home} cannot play itself.`;
    const key = `${home}:${away}`;
    if (pairs.has(key)) return `Match ${home} vs ${away} appears twice.`;
    pairs.add(key);
    for (const goals of [homeGoals, awayGoals]) {
      if (!Number.isInteger(goals) || goals < 0) return `Match ${home} vs ${away} needs non-negative goal counts.`;
    }
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pool = ['Ajax', 'Arsenal', 'Dortmund', 'Benfica', 'Celtic', 'Porto', 'Inter', 'Lyon', 'Napoli', 'Roma'];
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
    return list;
  };
  const teamCount = small ? Math.floor(rand() * 7) : 200;
  const ids = shuffle(Array.from({ length: small ? 9 : 400 }, (_, i) => i + 1)).slice(0, teamCount);
  const names = small ? shuffle(pool.slice()) : [];
  const Teams = ids.map((id, i) => [id, small ? names[i] : `${pool[id % pool.length]} ${id}`]);
  // Every ordered pair of different teams is a possible match; small cases use few goals so draws and ties are common.
  const pairs = [];
  for (const home of ids) for (const away of ids) if (home !== away) pairs.push([home, away]);
  shuffle(pairs);
  const matchCount = small ? Math.min(pairs.length, Math.floor(rand() * 9)) : Math.min(pairs.length, 2000);
  const maxGoals = small ? 3 : 6;
  const Matches = pairs.slice(0, matchCount).map(([home, away]) => [home, away, Math.floor(rand() * maxGoals), Math.floor(rand() * maxGoals)]);
  return [{ Teams, Matches }];
}
